import json
from dataclasses import dataclass

@dataclass(frozen=True, slots=True)
class Order:
    customer: str
    amount: float

def decode(payload: str) -> list[dict]:
    return json.loads(payload)

def validate(rows: list[dict]) -> list[Order]:
    orders = []
    for row in rows:
        if row.get("status") == "PAID" and float(row.get("amount", 0)) > 0:
            orders.append(Order(row["customer"], float(row["amount"])))
    return orders

def aggregate(orders: list[Order]) -> float:
    return sum(order.amount for order in orders)

